/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/checkbox.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
"use client";

import * as React from "react";
import { CheckIcon } from "lucide-react";
import { Checkbox as CheckboxPrimitive } from "radix-ui";
import { cn } from "@/lib/utils";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
function Checkbox({
  className,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root> & CapconsBasePropsLoose) {
  return <CheckboxPrimitive.Root data-slot="checkbox" className={cn("peer size-4 shrink-0 rounded-[4px] border border-input shadow-xs transition-shadow outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground dark:bg-input/30 dark:aria-invalid:ring-destructive/40 dark:data-[state=checked]:bg-primary", className)} {...capconsSpread(props)}>
      <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="grid place-content-center text-current transition-none">
        <CheckIcon className="size-3.5" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>;
}
export { Checkbox };
